dialect.statement:

UPDATE {table}
SET occupied = occupied + ?, gmt_modified = CURRENT_TIMESTAMP
WHERE quota_key = ? AND occupied + frozen + ? <= total_amount


UPDATE {table}
SET occupied = occupied - ?, gmt_modified = CURRENT_TIMESTAMP
WHERE quota_key = ? AND occupied >= ?


UPDATE {table}
SET frozen = frozen + ?, gmt_modified = CURRENT_TIMESTAMP
WHERE quota_key = ? AND occupied + frozen + ? <= total_amount


UPDATE {table}
SET frozen = frozen - ?, gmt_modified = CURRENT_TIMESTAMP
WHERE quota_key = ? AND frozen >= ?


UPDATE {table}
SET frozen = frozen - ?, occupied = occupied + ?, gmt_modified = CURRENT_TIMESTAMP
WHERE quota_key = ? AND frozen >= ?


UPDATE {table}
SET total_amount = total_amount + ?, gmt_modified = CURRENT_TIMESTAMP
WHERE quota_key = ? AND total_amount + ? >= occupied + frozen
